/* With GX_ENABLE_CANVAS_PARTIAL_FRAME_BUFFER, the 565rgb canvas copy, canvas
   blend and block move on a canvas that holds a whole frame and on one that
   holds part of a frame.

   gx_canvas_memory_define marks a canvas whose memory is smaller than a frame
   as a partial frame buffer. The canvas copy and canvas blend read a whole
   frame from the canvas memory, so on such a canvas they do nothing.

   Copy and blend are reached the way an application reaches them: three
   managed canvases and a composite canvas, and gx_system_canvas_refresh,
   which copies the lowest visible canvas into the composite and blends the
   one above it, which has a canvas alpha. First both hold a whole frame;
   then the lowest is replaced by a partial one, which is not copied; then the
   upper one, which is not blended. Before each refresh the composite is
   filled with a pattern, and after it the whole composite is compared with a
   model, and every canvas memory with what was put there.

   gx_canvas_block_move refuses a partial canvas itself and reports that it
   did not move the block. So the block move is called through the display
   for the partial canvas, inside drawing initiate and complete as
   gx_canvas_block_move calls it, and leaves the canvas memory as it was. On a
   canvas holding a whole frame, gx_canvas_block_move moves the block. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_system.h"
#include "gx_canvas.h"
#include "gx_display.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_partial_frame_buffer_16bpp_canvas_ops_no_output", /* Test name */
    0, 0, 0, 0  /* Define the coordinates of the capture area.*/
};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

#define TEST_WIDTH        40
#define TEST_HEIGHT       30
#define TEST_PIXELS       (TEST_WIDTH * TEST_HEIGHT)
#define TEST_TOP_WIDTH    16
#define TEST_TOP_HEIGHT   12
#define TEST_TOP_PIXELS   (TEST_TOP_WIDTH * TEST_TOP_HEIGHT)
#define TEST_TOP_X        28
#define TEST_TOP_Y        22
#define TEST_TOP_ALPHA    100

/* What a partial canvas is given: a quarter of its frame.  */
#define TEST_PARTIAL_BYTES(pixels) ((pixels) * sizeof(USHORT) / 4)

UINT gx_validation_graphics_driver_setup_565rgb(GX_DISPLAY *display);

static UINT       failed_tests = 0;

static TX_THREAD  test_thread;
static ULONG      test_thread_stack[8192 / sizeof(ULONG)];

static GX_DISPLAY test_display;

/* Bottom and top canvases holding a frame, their partial counterparts, the
   composite, and two simple canvases for the block move.  */
static GX_CANVAS  test_bottom;
static GX_CANVAS  test_top;
static GX_CANVAS  test_bottom_partial;
static GX_CANVAS  test_top_partial;
static GX_CANVAS  test_composite;
static GX_CANVAS  test_simple;
static GX_CANVAS  test_simple_partial;

static USHORT     test_bottom_memory[TEST_PIXELS];
static USHORT     test_top_memory[TEST_TOP_PIXELS];
static USHORT     test_bottom_partial_memory[TEST_PIXELS];
static USHORT     test_top_partial_memory[TEST_TOP_PIXELS];
static USHORT     test_composite_memory[TEST_PIXELS];
static USHORT     test_simple_memory[TEST_PIXELS];
static USHORT     test_simple_partial_memory[TEST_PIXELS];

static USHORT     test_model[TEST_PIXELS];

static USHORT test_value(INT index, UINT seed)
{
UINT value = ((UINT)index + seed) * 2654435761u;

    return (USHORT)(value ^ (value >> 15));
}

static VOID test_fill(USHORT *memory, INT pixels, UINT seed)
{
INT index;

    for (index = 0; index < pixels; index++)
    {
        memory[index] = test_value(index, seed);
    }
}

/* Compare memory with what test_fill put there, or with the model.  */
static VOID test_compare(char *label, char *what, USHORT *memory, INT pixels, UINT seed, USHORT *model)
{
INT    index;
USHORT expected;

    for (index = 0; index < pixels; index++)
    {
        expected = model ? model[index] : test_value(index, seed);
        if (memory[index] != expected)
        {
            printf("%s: %s at %d: expected 0x%04x, got 0x%04x\n", label, what, index, expected, memory[index]);
            failed_tests++;
            return;
        }
    }
}

/* The 565rgb canvas blend of one pixel.  */
static USHORT test_blend(USHORT background, USHORT foreground, UINT alpha)
{
UINT red = ((((background >> 11) & 0x1f) * (256 - alpha)) + (((foreground >> 11) & 0x1f) * alpha)) >> 8;
UINT green = ((((background >> 5) & 0x3f) * (256 - alpha)) + (((foreground >> 5) & 0x3f) * alpha)) >> 8;
UINT blue = (((background & 0x1f) * (256 - alpha)) + ((foreground & 0x1f) * alpha)) >> 8;

    return (USHORT)(((red & 0x1f) << 11) | ((green & 0x3f) << 5) | (blue & 0x1f));
}

/* Put the top canvas into the model, copied or blended, where it lies on the
   composite.  */
static VOID test_model_top(USHORT *top_memory, GX_BOOL blend)
{
INT x;
INT y;
INT index;

    for (y = 0; y < TEST_TOP_HEIGHT; y++)
    {
        for (x = 0; x < TEST_TOP_WIDTH; x++)
        {
            if (TEST_TOP_X + x >= TEST_WIDTH || TEST_TOP_Y + y >= TEST_HEIGHT)
            {
                continue;
            }
            index = (TEST_TOP_Y + y) * TEST_WIDTH + TEST_TOP_X + x;
            if (blend)
            {
                test_model[index] = test_blend(test_model[index], top_memory[y * TEST_TOP_WIDTH + x], TEST_TOP_ALPHA);
            }
            else
            {
                test_model[index] = top_memory[y * TEST_TOP_WIDTH + x];
            }
        }
    }
}

/* Fill every canvas memory and the composite, refresh, and compare.  */
static VOID test_refresh(char *label)
{
    test_fill(test_bottom_memory, TEST_PIXELS, 11);
    test_fill(test_top_memory, TEST_TOP_PIXELS, 23);
    test_fill(test_bottom_partial_memory, TEST_PIXELS, 37);
    test_fill(test_top_partial_memory, TEST_TOP_PIXELS, 41);
    test_fill(test_composite_memory, TEST_PIXELS, 53);

    EXPECT_EQ(GX_SUCCESS, gx_system_canvas_refresh());

    test_compare(label, "composite", test_composite_memory, TEST_PIXELS, 0, test_model);
    test_compare(label, "bottom canvas", test_bottom_memory, TEST_PIXELS, 11, GX_NULL);
    test_compare(label, "top canvas", test_top_memory, TEST_TOP_PIXELS, 23, GX_NULL);
    test_compare(label, "partial bottom canvas", test_bottom_partial_memory, TEST_PIXELS, 37, GX_NULL);
    test_compare(label, "partial top canvas", test_top_partial_memory, TEST_TOP_PIXELS, 41, GX_NULL);
}

static VOID test_composite_sequence(VOID)
{
    /* Created lowest first: the composite is built from the oldest canvas up.  */
    EXPECT_EQ(GX_SUCCESS, gx_canvas_create(&test_bottom, "test_bottom", &test_display, GX_CANVAS_MANAGED,
                                           TEST_WIDTH, TEST_HEIGHT, (GX_COLOR *)test_bottom_memory,
                                           sizeof(test_bottom_memory)));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_create(&test_top, "test_top", &test_display, GX_CANVAS_MANAGED,
                                           TEST_TOP_WIDTH, TEST_TOP_HEIGHT, (GX_COLOR *)test_top_memory,
                                           sizeof(test_top_memory)));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_create(&test_bottom_partial, "test_bottom_partial", &test_display,
                                           GX_CANVAS_MANAGED, TEST_WIDTH, TEST_HEIGHT,
                                           (GX_COLOR *)test_bottom_partial_memory,
                                           sizeof(test_bottom_partial_memory)));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_create(&test_top_partial, "test_top_partial", &test_display,
                                           GX_CANVAS_MANAGED, TEST_TOP_WIDTH, TEST_TOP_HEIGHT,
                                           (GX_COLOR *)test_top_partial_memory,
                                           sizeof(test_top_partial_memory)));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_create(&test_composite, "test_composite", &test_display, GX_CANVAS_COMPOSITE,
                                           TEST_WIDTH, TEST_HEIGHT, (GX_COLOR *)test_composite_memory,
                                           sizeof(test_composite_memory)));

    EXPECT_EQ(GX_SUCCESS, gx_canvas_offset_set(&test_top, TEST_TOP_X, TEST_TOP_Y));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_offset_set(&test_top_partial, TEST_TOP_X, TEST_TOP_Y));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_alpha_set(&test_top, TEST_TOP_ALPHA));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_alpha_set(&test_top_partial, TEST_TOP_ALPHA));

    /* A quarter of a frame each: partial frame buffers.  */
    EXPECT_EQ(GX_SUCCESS, gx_canvas_memory_define(&test_bottom_partial, (GX_COLOR *)test_bottom_partial_memory,
                                                  TEST_PARTIAL_BYTES(TEST_PIXELS)));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_memory_define(&test_top_partial, (GX_COLOR *)test_top_partial_memory,
                                                  TEST_PARTIAL_BYTES(TEST_TOP_PIXELS)));
    EXPECT_EQ(0, test_bottom.gx_canvas_status & GX_CANVAS_PARTIAL_FRAME_BUFFER);
    EXPECT_EQ(0, test_top.gx_canvas_status & GX_CANVAS_PARTIAL_FRAME_BUFFER);
    EXPECT_EQ(GX_CANVAS_PARTIAL_FRAME_BUFFER, test_bottom_partial.gx_canvas_status & GX_CANVAS_PARTIAL_FRAME_BUFFER);
    EXPECT_EQ(GX_CANVAS_PARTIAL_FRAME_BUFFER, test_top_partial.gx_canvas_status & GX_CANVAS_PARTIAL_FRAME_BUFFER);

    /* Each refresh is preceded by showing a canvas the size of the composite,
       which marks all of it dirty, so the whole composite is rebuilt.  */

    /* Both whole frames: the bottom copied, the top blended over it.  */
    EXPECT_EQ(GX_SUCCESS, gx_canvas_show(&test_top));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_show(&test_bottom));
    test_fill(test_bottom_memory, TEST_PIXELS, 11);
    test_fill(test_top_memory, TEST_TOP_PIXELS, 23);
    memcpy(test_model, test_bottom_memory, sizeof(test_model));
    test_model_top(test_top_memory, GX_TRUE);
    test_refresh("whole frames");

    /* The lowest visible canvas is now the top one, so it is copied; the
       partial bottom canvas above it is not.  */
    EXPECT_EQ(GX_SUCCESS, gx_canvas_hide(&test_bottom));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_show(&test_bottom_partial));
    test_fill(test_composite_memory, TEST_PIXELS, 53);
    memcpy(test_model, test_composite_memory, sizeof(test_model));
    test_model_top(test_top_memory, GX_FALSE);
    test_refresh("partial bottom");

    /* The bottom copied; the partial top canvas, with its alpha, not blended.  */
    EXPECT_EQ(GX_SUCCESS, gx_canvas_hide(&test_top));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_hide(&test_bottom_partial));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_show(&test_top_partial));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_show(&test_bottom));
    test_fill(test_bottom_memory, TEST_PIXELS, 11);
    memcpy(test_model, test_bottom_memory, sizeof(test_model));
    test_refresh("partial top");

    EXPECT_EQ(GX_SUCCESS, gx_canvas_hide(&test_bottom));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_hide(&test_top_partial));
}

static VOID test_block_move_sequence(VOID)
{
GX_RECTANGLE dirty;
GX_RECTANGLE block;
GX_RECTANGLE rest;
INT          x;
INT          y;

    EXPECT_EQ(GX_SUCCESS, gx_canvas_create(&test_simple, "test_simple", &test_display, GX_CANVAS_SIMPLE,
                                           TEST_WIDTH, TEST_HEIGHT, (GX_COLOR *)test_simple_memory,
                                           sizeof(test_simple_memory)));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_create(&test_simple_partial, "test_simple_partial", &test_display,
                                           GX_CANVAS_SIMPLE, TEST_WIDTH, TEST_HEIGHT,
                                           (GX_COLOR *)test_simple_partial_memory,
                                           sizeof(test_simple_partial_memory)));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_memory_define(&test_simple_partial, (GX_COLOR *)test_simple_partial_memory,
                                                  TEST_PARTIAL_BYTES(TEST_PIXELS)));
    EXPECT_EQ(0, test_simple.gx_canvas_status & GX_CANVAS_PARTIAL_FRAME_BUFFER);
    EXPECT_EQ(GX_CANVAS_PARTIAL_FRAME_BUFFER, test_simple_partial.gx_canvas_status & GX_CANVAS_PARTIAL_FRAME_BUFFER);

    gx_utility_rectangle_define(&dirty, 8, 6, 27, 15);
    gx_utility_rectangle_define(&block, 10, 7, 25, 13);

    /* A whole frame: the block moves 3 pixels right, and the 3 columns it
       leaves are reported for redrawing.  */
    test_fill(test_simple_memory, TEST_PIXELS, 67);
    test_fill(test_model, TEST_PIXELS, 67);
    for (y = block.gx_rectangle_top; y <= block.gx_rectangle_bottom; y++)
    {
        for (x = block.gx_rectangle_right - 3; x >= block.gx_rectangle_left; x--)
        {
            test_model[y * TEST_WIDTH + x + 3] = test_model[y * TEST_WIDTH + x];
        }
    }
    EXPECT_EQ(GX_SUCCESS, gx_canvas_drawing_initiate(&test_simple, GX_NULL, &dirty));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_block_move(&block, 3, 0, &rest));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_drawing_complete(&test_simple, GX_FALSE));
    EXPECT_EQ(block.gx_rectangle_left, rest.gx_rectangle_left);
    EXPECT_EQ(block.gx_rectangle_left + 2, rest.gx_rectangle_right);
    EXPECT_EQ(block.gx_rectangle_top, rest.gx_rectangle_top);
    EXPECT_EQ(block.gx_rectangle_bottom, rest.gx_rectangle_bottom);
    test_compare("whole frame", "block moved", test_simple_memory, TEST_PIXELS, 0, test_model);

    /* A partial frame: gx_canvas_block_move does not move it, and the display's
       block move, called directly, leaves the memory as it was.  */
    test_fill(test_simple_partial_memory, TEST_PIXELS, 79);
    EXPECT_EQ(GX_SUCCESS, gx_canvas_drawing_initiate(&test_simple_partial, GX_NULL, &dirty));
    EXPECT_EQ(GX_FAILURE, gx_canvas_block_move(&block, 3, 0, &rest));
    _gx_system_current_draw_context -> gx_draw_context_clip = &block;
    test_display.gx_display_driver_block_move(_gx_system_current_draw_context, &block, 3, 0);
    EXPECT_EQ(GX_SUCCESS, gx_canvas_drawing_complete(&test_simple_partial, GX_FALSE));
    test_compare("partial frame", "block not moved", test_simple_partial_memory, TEST_PIXELS, 79, GX_NULL);
}

static VOID test_thread_entry(ULONG id)
{
    gx_system_initialize();

    EXPECT_EQ(GX_SUCCESS, gx_display_create(&test_display, "test_display", gx_validation_graphics_driver_setup_565rgb,
                                            TEST_WIDTH, TEST_HEIGHT));
    EXPECT_EQ(GX_COLOR_FORMAT_565RGB, test_display.gx_display_color_format);

    test_composite_sequence();
    test_block_move_sequence();

    if (failed_tests)
    {
        gx_validation_print_test_result(TEST_FAIL);
    }
    else
    {
        gx_validation_print_test_result(TEST_SUCCESS);
    }

    exit(failed_tests);
}

VOID tx_application_define(void *first_unused_memory)
{
    tx_thread_create(&test_thread, "test_thread", test_thread_entry, 0,
                     test_thread_stack, sizeof(test_thread_stack),
                     1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);
}

